{
  "name": "@herouucn/opencode-commandcode",
  "version": "0.1.12",
  "description": "Inject Command Code API provider into opencode — access Claude, GPT, Gemini, DeepSeek, Qwen, Kimi, GLM, MiniMax & Step via unified Command Code API. / 将 Command Code API provider 注入 opencode —— 通过统一的 Command Code API 使用 Claude、GPT、Gemini、DeepSeek、Qwen、Kimi、GLM、MiniMax 和 Step 模型。",
  "keywords": [
    "ai",
    "claude",
    "commandcode",
    "deepseek",
    "gemini",
    "glm",
    "gpt",
    "kimi",
    "llm",
    "minimax",
    "opencode",
    "opencode-plugin",
    "opencode-provider",
    "qwen"
  ],
  "homepage": "https://github.com/herouu/opencode-commandcode#readme",
  "bugs": {
    "url": "https://github.com/herouu/opencode-commandcode/issues"
  },
  "license": "MIT",
  "author": "herouu",
  "repository": {
    "type": "git",
    "url": "https://github.com/herouu/opencode-commandcode"
  },
  "files": [
    "index.ts",
    "plugin/",
    "core/",
    "models.json",
    "manifest.json",
    "_version.txt",
    "README.md",
    "src/"
  ],
  "type": "module",
  "main": "index.ts",
  "types": "index.ts",
  "exports": {
    ".": {
      "import": "./index.ts"
    },
    "./server": {
      "import": "./plugin/index.ts"
    },
    "./plugin": {
      "import": "./plugin/index.ts"
    },
    "./plugin.v1": {
      "import": "./plugin/v1.ts"
    },
    "./plugin.v2": {
      "import": "./plugin/v2.ts"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "lint": "oxlint --deny-warnings src scripts core plugin index.ts tests",
    "lint:fix": "oxlint --fix src scripts core plugin index.ts tests",
    "format": "oxfmt src scripts core plugin index.ts tests package.json tsconfig.json",
    "format:check": "oxfmt --check src scripts core plugin index.ts tests package.json tsconfig.json",
    "check": "bun run lint && bun run format:check && bun test tests/unit/ && bun run typecheck",
    "test": "bun test tests/unit/",
    "test:integration": "bun test tests/integration/",
    "test:all": "bun test",
    "typecheck": "tsc --noEmit",
    "sync": "bun run scripts/sync-models.ts",
    "sync:global": "bun run scripts/sync-models.ts --update-global",
    "catalog:ci": "bun run scripts/catalog-sync-ci.ts"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.27",
    "@types/node": "^25.9.1",
    "oxfmt": "0.63.0",
    "oxlint": "1.78.0",
    "typescript": "^6.0.3"
  },
  "peerDependencies": {
    "ai": ">=6.0.0"
  },
  "engines": {
    "bun": ">=1.0.0"
  }
}
